 const kind=category.id;let drawing='';
 const board=`<polygon points="63,71 178,51 255,84 141,107" fill="url(#lid)"/><polygon points="63,71 141,107 141,173 63,139" fill="#554a42"/><polygon points="141,107 255,84 255,144 141,173" fill="url(#box)"/><polygon points="63,71 178,51 255,84 141,107" fill="none" stroke="#ecdfd1" stroke-width="2"/><path d="M140 108v65" stroke="#9b8671" stroke-width="1"/><text x="185" y="121" fill="#d7b986" font-family="serif" font-size="12" text-anchor="middle" letter-spacing="3">D P</text>`;
