 if(b.dataset.openTicket){const values=await requestForm({title:'Contact customer care',description:'Describe an order change, delivery issue, quality concern or refund enquiry. Our team will review your request.',confirm:'Submit service request',fields:[{name:'category',label:'Issue category',type:'select',options:['order_change','artwork','quality','delivery','payment','refund','other'].map(v=>({value:v,label:v.replaceAll('_',' ')}))},{name:'subject',label:'Short subject',minlength:5,maxlength:160},{name:'message',label:'Details of the issue',type:'textarea',minlength:10,maxlength:3000}]});if(!values)return;const result=await action('/tickets',{orderId:b.dataset.openTicket,...values},'POST','Your request has been recorded.');if(result){state.workspaceTab='tickets';await loadWorkspace();}return;}
